package com.sakalti.modifier;
import net.minecraft.entity.effect.*; import net.minecraft.entity.LivingEntity; import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.context.ToolAttackContext; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class HeavyStoneModifier extends Modifier { @Override public int afterEntityHit(IToolStackView tool,int level,ToolAttackContext ctx,float damage){LivingEntity a=ctx.getAttacker();if(a!=null&&!a.getWorld().isClient){a.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,100,4));a.addStatusEffect(new StatusEffectInstance(StatusEffects.RESISTANCE,100,2));}return 0;}}
